//! Videos' frames drawn by Vulkan from the decoder's own buffer (`video` with `gpu-draw`): no
//! frame is read back while it plays.
//!
//! - Android: the image reader's hardware buffer, imported as an image
//!   (`VK_ANDROID_external_memory_android_hardware_buffer`), of the driver's own format.
//! - Linux: a dmabuf of linear NV12 or I420, imported as a buffer (`VK_EXT_external_memory_dma_buf`);
//!   its planes are copied, on the GPU, into an image of two or three planes.
//! - Each frame is read through a sampler Y′CbCr conversion of the identity model, full range,
//!   nearest: its planes' bytes as they are, each pixel's chroma the sample of its 2 × 2. The
//!   shaders make them RGB as the CPU does (`video_yuv::FROM_YUV`), so both give the same
//!   pixels.
//! - The conversion is part of the frames' descriptor set layout, so of their pipeline: one is
//!   made for the kind of frame drawn, and a part showing frames of two kinds is drawn by the CPU.
use crate::gpu_draw::MOST_FRAMES;
use crate::gpu_draw_vulkan::Pipeline;
use crate::gpu_vulkan::Vulkan;
use crate::layer_vulkan::{
    VkDescriptorImageInfo, VkDescriptorPoolCreateInfo, VkDescriptorPoolSize, VkDescriptorSetAllocateInfo, VkDescriptorSetLayoutBinding, VkDescriptorSetLayoutCreateInfo, VkPipelineLayoutCreateInfo,
    VkWriteDescriptorSet,
};
use crate::video::FrameTexture;
use crate::vk::*;
use std::ffi::{CStr, c_void};
use std::ptr::null;
use std::sync::Arc;

structures! {
    VkSamplerYcbcrConversionCreateInfo { kind: u32, next: *const c_void, format: u32, model: u32, range: u32, components: [u32; 4], x_offset: u32, y_offset: u32, filter: u32, explicit: u32, }
    VkSamplerYcbcrConversionInfo { kind: u32, next: *const c_void, conversion: Handle, }
    VkPhysicalDeviceSamplerYcbcrConversionFeatures { kind: u32, next: *mut c_void, enabled: u32, }
    VkPhysicalDeviceFeatures2 { kind: u32, next: *mut c_void, features: [u32; 55], }
    VkPushConstantRange { stages: u32, offset: u32, size: u32, }
    VkMemoryDedicatedAllocateInfo { kind: u32, next: *const c_void, image: Handle, buffer: Handle, }
}

#[cfg(target_os = "android")]
structures! {
    VkExternalMemoryImageCreateInfo { kind: u32, next: *const c_void, handles: u32, }
    VkExternalFormatANDROID { kind: u32, next: *mut c_void, format: u64, }
    VkAndroidHardwareBufferPropertiesANDROID { kind: u32, next: *mut c_void, size: u64, memory_types: u32, }
    VkAndroidHardwareBufferFormatPropertiesANDROID { kind: u32, next: *mut c_void, format: u32, external_format: u64, features: u32, components: [u32; 4], model: u32, range: u32, x_offset: u32, y_offset: u32, }
    VkImportAndroidHardwareBufferInfoANDROID { kind: u32, next: *const c_void, buffer: *mut c_void, }
}

#[cfg(not(target_os = "android"))]
structures! {
    VkExternalMemoryBufferCreateInfo { kind: u32, next: *const c_void, handles: u32, }
    VkImportMemoryFdInfoKHR { kind: u32, next: *const c_void, handle: u32, fd: i32, }
    VkMemoryFdPropertiesKHR { kind: u32, next: *mut c_void, memory_types: u32, }
    VkFormatProperties { linear: u32, optimal: u32, buffer: u32, }
}

functions!(Calls {
    vkCreateSamplerYcbcrConversion: fn(Object, *const VkSamplerYcbcrConversionCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroySamplerYcbcrConversion: fn(Object, Handle, *const c_void);
    vkCreateSampler: fn(Object, *const VkSamplerCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroySampler: fn(Object, Handle, *const c_void);
    vkCreateDescriptorSetLayout: fn(Object, *const VkDescriptorSetLayoutCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyDescriptorSetLayout: fn(Object, Handle, *const c_void);
    vkCreateDescriptorPool: fn(Object, *const VkDescriptorPoolCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyDescriptorPool: fn(Object, Handle, *const c_void);
    vkAllocateDescriptorSets: fn(Object, *const VkDescriptorSetAllocateInfo, *mut Handle) -> i32;
    vkUpdateDescriptorSets: fn(Object, u32, *const VkWriteDescriptorSet, u32, *const c_void);
    vkCreatePipelineLayout: fn(Object, *const VkPipelineLayoutCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyPipelineLayout: fn(Object, Handle, *const c_void);
    vkDestroyPipeline: fn(Object, Handle, *const c_void);
    vkCreateImage: fn(Object, *const VkImageCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyImage: fn(Object, Handle, *const c_void);
    vkGetImageMemoryRequirements: fn(Object, Handle, *mut VkMemoryRequirements);
    vkBindImageMemory: fn(Object, Handle, Handle, u64) -> i32;
    vkCreateImageView: fn(Object, *const VkImageViewCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyImageView: fn(Object, Handle, *const c_void);
    vkAllocateMemory: fn(Object, *const VkMemoryAllocateInfo, *const c_void, *mut Handle) -> i32;
    vkFreeMemory: fn(Object, Handle, *const c_void);
    vkCmdPipelineBarrier: fn(Object, u32, u32, u32, u32, *const c_void, u32, *const c_void, u32, *const VkImageMemoryBarrier);
    vkCmdBindPipeline: fn(Object, u32, Handle);
    vkCmdBindDescriptorSets: fn(Object, u32, Handle, u32, u32, *const Handle, u32, *const u32);
    vkCmdPushConstants: fn(Object, Handle, u32, u32, u32, *const c_void);
    #[cfg(target_os = "android")]
    vkGetAndroidHardwareBufferPropertiesANDROID: fn(Object, *mut c_void, *mut VkAndroidHardwareBufferPropertiesANDROID) -> i32;
    #[cfg(not(target_os = "android"))]
    vkGetMemoryFdPropertiesKHR: fn(Object, u32, i32, *mut VkMemoryFdPropertiesKHR) -> i32;
    #[cfg(not(target_os = "android"))]
    vkCreateBuffer: fn(Object, *const VkBufferCreateInfo, *const c_void, *mut Handle) -> i32;
    #[cfg(not(target_os = "android"))]
    vkDestroyBuffer: fn(Object, Handle, *const c_void);
    #[cfg(not(target_os = "android"))]
    vkGetBufferMemoryRequirements: fn(Object, Handle, *mut VkMemoryRequirements);
    #[cfg(not(target_os = "android"))]
    vkBindBufferMemory: fn(Object, Handle, Handle, u64) -> i32;
    #[cfg(not(target_os = "android"))]
    vkCmdCopyBufferToImage: fn(Object, Handle, Handle, u32, u32, *const VkBufferImageCopy);
});

/// The device extensions that import the decoder's buffers.
#[cfg(target_os = "android")]
const EXTENSIONS: [&CStr; 2] = [c"VK_ANDROID_external_memory_android_hardware_buffer", c"VK_EXT_queue_family_foreign"];
#[cfg(not(target_os = "android"))]
const EXTENSIONS: [&CStr; 2] = [c"VK_KHR_external_memory_fd", c"VK_EXT_external_memory_dma_buf"];

/// A format feature: a conversion may place chroma at the middle of its pixels (else on the
/// first; `TEXEL_GLSL` reads the CPU's sample either way).
const MIDPOINT_CHROMA: u32 = 0x2_0000;
/// The conversion's chroma places: at the middle; on the first pixel.
const MIDPOINT: u32 = 1;
const COSITED: u32 = 0;
/// The fragment shader stage, and the bytes of numbers it is pushed: eight for each frame.
const FRAGMENT: u32 = 0x10;
const PUSHED: u32 = (MOST_FRAMES * 8 * 4) as u32;
/// Imports kept (each frame's buffer is one of the decoder's few, used again and again).
const KEPT: usize = 8;

/// Whether device `physical` imports the decoder's buffers: Vulkan 1.1 with the extensions and
/// sampler Y′CbCr conversions. Its `extensions` are then to be asked for with
/// `CONVERSIONS` chained in.
pub(crate) fn imports(vulkan: &Vulkan, physical: Object) -> bool {
    let features = vulkan.function(c"vkGetPhysicalDeviceFeatures2");
    if vulkan.properties(physical).api_version < crate::gpu_vulkan::VULKAN_1_1 || features.is_null() || !EXTENSIONS.iter().all(|name| vulkan.offers(physical, name)) {
        return false;
    }
    let mut conversions = VkPhysicalDeviceSamplerYcbcrConversionFeatures { kind: 1_000_156_004, ..Default::default() };
    let mut asked = VkPhysicalDeviceFeatures2 { kind: 1_000_059_000, next: (&raw mut conversions).cast(), ..Default::default() };
    // SAFETY: the function of that name, as vulkan_core.h declares it; it fills in the chain.
    unsafe { std::mem::transmute::<*const c_void, unsafe extern "system" fn(Object, *mut VkPhysicalDeviceFeatures2)>(features)(physical, &mut asked) };
    conversions.enabled != 0
}

/// The extensions a device that `imports` is made with.
pub(crate) fn extensions() -> [&'static CStr; 2] {
    EXTENSIONS
}

/// What a device that `imports` is made with chained in: sampler Y′CbCr conversions on.
pub(crate) fn conversions_on() -> VkPhysicalDeviceSamplerYcbcrConversionFeatures {
    VkPhysicalDeviceSamplerYcbcrConversionFeatures { kind: 1_000_156_004, enabled: 1, ..Default::default() }
}

/// A kind of frame: what tells it apart (Android: the format, else its driver's own; Linux: the
/// format), its conversion and the sampler through it, the descriptor set naming four frames
/// (its layout, pool) and the pipeline drawing them (its layout).
struct Kind {
    key: [u64; 2],
    conversion: Handle,
    sampler: Handle,
    set_layout: Handle,
    pool: Handle,
    set: Handle,
    layout: Handle,
    pipeline: Handle,
}

/// A decoder's buffer imported: which (`key`), the image of it, its memory and view, and
/// whether the image was given back to the decoder since first used. Android: the hardware
/// buffer, held while imported; Linux: the dmabuf as a buffer, and its memory.
struct Imported {
    key: u64,
    image: Handle,
    memory: Handle,
    view: Handle,
    #[cfg(target_os = "android")]
    used: bool,
    #[cfg(target_os = "android")]
    _held: crate::video_android::HeldBuffer,
    #[cfg(not(target_os = "android"))]
    buffer: Handle,
    #[cfg(not(target_os = "android"))]
    buffer_memory: Handle,
}

/// What draws videos' frames on a device that `imports`: its functions, the device and its
/// queue family, the format features of the Linux frames' formats, the kind of frame drawn, the
/// buffers imported (the newest last), and this part's frames: their imports and the numbers
/// that make them RGB.
pub(crate) struct Frames {
    calls: Calls,
    device: Object,
    #[cfg(target_os = "android")]
    family: u32,
    #[cfg(not(target_os = "android"))]
    planar: [u32; 2],
    kind: Option<Kind>,
    imported: Vec<Imported>,
    drawn: Vec<usize>,
    numbers: [f32; MOST_FRAMES * 8],
}

// SAFETY: as its device: used by one thread at a time.
unsafe impl Send for Frames {}

impl Frames {
    /// What draws frames on `device` (whose queues are of `family`), its functions found by
    /// `find`; `vulkan`'s device `physical` tells what its formats can do. None where a function
    /// is missing.
    pub(crate) fn new(find: &mut dyn FnMut(&CStr) -> *const c_void, device: Object, family: u32, vulkan: &Vulkan, physical: Object) -> Option<Box<Frames>> {
        let calls = Calls::load(find).ok()?;
        #[cfg(target_os = "android")]
        let _ = (vulkan, physical);
        #[cfg(not(target_os = "android"))]
        let _ = family;
        Some(Box::new(Frames {
            calls,
            device,
            #[cfg(target_os = "android")]
            family,
            #[cfg(not(target_os = "android"))]
            planar: [TWO_PLANES, THREE_PLANES].map(|format| optimal_features(vulkan, physical, format)),
            kind: None,
            imported: Vec::new(),
            drawn: Vec::new(),
            numbers: [0.0; MOST_FRAMES * 8],
        }))
    }

    /// Readies `frames` (this part's) to be drawn: each imported, laid out for the shaders and
    /// named by the descriptor set of their kind's pipeline. Whether they are (none can be
    /// where the frames are of two kinds, or one can't be imported).
    pub(crate) fn ready(&mut self, pipeline: &Pipeline, commands: Object, frames: &[Arc<FrameTexture>]) -> bool {
        self.drawn.clear();
        let Some(first) = frames.first() else { return true };
        let Some(kind) = self.kind_of(first) else { return false };
        if !frames.iter().all(|frame| self.kind_of(frame).is_some_and(|other| other.key == kind.key)) || !self.make_kind(pipeline, kind) {
            return false;
        }
        for (nth, frame) in frames.iter().enumerate() {
            let Some(at) = self.import(pipeline, frame) else { return false };
            self.lay_out(commands, at, frame);
            self.drawn.push(at);
            self.numbers[nth * 8..nth * 8 + 8].copy_from_slice(&frame.for_shaders());
        }
        self.name_frames();
        true
    }

    /// Binds the frames' pipeline, the descriptor sets (`set` the cache and patches') and the
    /// numbers into `commands` (in a render pass), where this part has frames: whether it does.
    pub(crate) fn bind(&self, commands: Object, set: Handle) -> bool {
        let Some(kind) = self.kind.as_ref().filter(|_| !self.drawn.is_empty()) else { return false };
        let (calls, sets) = (&self.calls, [set, kind.set]);
        // SAFETY: the commands are being recorded; the pipeline and sets are alive, and the
        // numbers as many as the pipeline's layout takes.
        unsafe {
            (calls.vkCmdBindPipeline)(commands, 0, kind.pipeline);
            (calls.vkCmdBindDescriptorSets)(commands, 0, kind.layout, 0, 2, sets.as_ptr(), 0, null());
            (calls.vkCmdPushConstants)(commands, kind.layout, FRAGMENT, 0, PUSHED, self.numbers.as_ptr().cast());
        }
        true
    }

    /// Makes the pipeline of frames of `kind` where it is not the one made: the conversion and
    /// what names frames through it, then the pipeline. What was made for the kind before goes,
    /// and the buffers imported with it. Whether it is made.
    fn make_kind(&mut self, pipeline: &Pipeline, kind: KindOf) -> bool {
        if self.kind.as_ref().is_some_and(|made| made.key == kind.key) {
            return true;
        }
        self.forget_kind();
        let Some(conversion) = self.conversion(&kind) else { return false };
        let mut made = Kind { key: kind.key, conversion, sampler: 0, set_layout: 0, pool: 0, set: 0, layout: 0, pipeline: 0 };
        let complete = self.sampler(&mut made) && self.set(&mut made, pipeline.set_layout());
        made.pipeline = if complete { pipeline.pipeline(&PIXELS_FRAMES, made.layout).unwrap_or(0) } else { 0 };
        let ready = made.pipeline != 0;
        self.kind = Some(made);
        ready
    }

    /// A conversion of frames of `kind`: the identity model, full range, nearest, chroma at the
    /// middle of its pixels where the format can (else on the first).
    fn conversion(&self, kind: &KindOf) -> Option<Handle> {
        let place = if kind.features & MIDPOINT_CHROMA != 0 { MIDPOINT } else { COSITED };
        let asked = VkSamplerYcbcrConversionCreateInfo { kind: 1_000_156_000, next: kind.chained(), format: kind.format, x_offset: place, y_offset: place, ..Default::default() };
        let mut conversion = 0;
        // SAFETY: the device is alive; the description and what it chains live through the call.
        (unsafe { (self.calls.vkCreateSamplerYcbcrConversion)(self.device, &asked, null(), &mut conversion) } == 0).then_some(conversion)
    }

    /// The sampler through `made`'s conversion: nearest, clamped. Whether it is made.
    fn sampler(&self, made: &mut Kind) -> bool {
        let through = VkSamplerYcbcrConversionInfo { kind: 1_000_156_001, conversion: made.conversion, ..Default::default() };
        let asked = VkSamplerCreateInfo { kind: 31, next: (&raw const through).cast(), address: [2; 3], ..Default::default() };
        // SAFETY: as above.
        unsafe { (self.calls.vkCreateSampler)(self.device, &asked, null(), &mut made.sampler) == 0 }
    }

    /// The descriptor set naming four frames through `made`'s sampler (set 1; `set_layout` is
    /// set 0's), its layout and pool, and the pipeline's layout with the numbers pushed.
    /// Whether all are made.
    fn set(&self, made: &mut Kind, set_layout: Handle) -> bool {
        let binding = |at: u32| VkDescriptorSetLayoutBinding { binding: at, descriptor_type: SAMPLED, count: 1, stages: FRAGMENT, samplers: &made.sampler };
        let bindings = [0, 1, 2, 3].map(binding);
        // (A frame of several planes may take a descriptor for each.)
        let sizes = VkDescriptorPoolSize { descriptor_type: SAMPLED, count: (MOST_FRAMES * 3) as u32 };
        let pushed = VkPushConstantRange { stages: FRAGMENT, offset: 0, size: PUSHED };
        let (calls, device) = (&self.calls, self.device);
        // SAFETY: the device is alive; each description is whole and what it points to lives
        // through the call. What is made is held by the kind.
        unsafe {
            let described = VkDescriptorSetLayoutCreateInfo { kind: 32, binding_count: 4, bindings: bindings.as_ptr(), ..Default::default() };
            let pooled = VkDescriptorPoolCreateInfo { kind: 33, max_sets: 1, size_count: 1, sizes: &sizes, ..Default::default() };
            if (calls.vkCreateDescriptorSetLayout)(device, &described, null(), &mut made.set_layout) != 0 || (calls.vkCreateDescriptorPool)(device, &pooled, null(), &mut made.pool) != 0 {
                return false;
            }
            let layouts = [set_layout, made.set_layout];
            let asked = VkDescriptorSetAllocateInfo { kind: 34, pool: made.pool, count: 1, layouts: &made.set_layout, ..Default::default() };
            let laid = VkPipelineLayoutCreateInfo { kind: 30, set_layout_count: 2, set_layouts: layouts.as_ptr(), push_range_count: 1, push_ranges: (&raw const pushed).cast(), ..Default::default() };
            (calls.vkAllocateDescriptorSets)(device, &asked, &mut made.set) == 0 && (calls.vkCreatePipelineLayout)(device, &laid, null(), &mut made.layout) == 0
        }
    }

    /// Names this part's frames in the kind's descriptor set: frame n at binding n; the first
    /// where there are fewer.
    fn name_frames(&self) {
        let Some(kind) = &self.kind else { return };
        let images: [VkDescriptorImageInfo; MOST_FRAMES] = std::array::from_fn(|nth| {
            let at = self.drawn.get(nth).or(self.drawn.first()).copied().unwrap_or_default();
            VkDescriptorImageInfo { sampler: 0, view: self.imported[at].view, layout: LAYOUT_SHADER_READ_ONLY }
        });
        let writes: [VkWriteDescriptorSet; MOST_FRAMES] =
            std::array::from_fn(|nth| VkWriteDescriptorSet { kind: 35, set: kind.set, binding: nth as u32, count: 1, descriptor_type: SAMPLED, images: &images[nth], ..Default::default() });
        // SAFETY: the set and views are alive; nothing the device runs uses the set now (each
        // submit is waited for); the writes point into `images`, alive here.
        unsafe { (self.calls.vkUpdateDescriptorSets)(self.device, MOST_FRAMES as u32, writes.as_ptr(), 0, null()) };
    }

    /// Where `frame`'s buffer is among those imported: found, or imported now (the oldest not
    /// in this part let go of where too many are). None where it can't be.
    fn import(&mut self, pipeline: &Pipeline, frame: &FrameTexture) -> Option<usize> {
        let key = frame.key()?;
        if let Some(at) = self.imported.iter().position(|imported| imported.key == key) {
            return Some(at);
        }
        if self.imported.len() >= KEPT
            && let Some(oldest) = (0..self.imported.len()).find(|at| !self.drawn.contains(at))
        {
            let gone = self.imported.remove(oldest);
            self.let_go_of(gone);
            self.drawn.iter_mut().filter(|at| **at > oldest).for_each(|at| *at -= 1);
        }
        let imported = self.imported_of(pipeline, frame, key)?;
        self.imported.push(imported);
        Some(self.imported.len() - 1)
    }

    /// A view of `image` through the kind's conversion; 0 where none is made.
    fn view(&self, image: Handle, format: u32) -> Handle {
        let Some(kind) = &self.kind else { return 0 };
        let through = VkSamplerYcbcrConversionInfo { kind: 1_000_156_001, conversion: kind.conversion, ..Default::default() };
        let seen = VkImageViewCreateInfo { kind: 15, next: (&raw const through).cast(), image, view_type: 1, format, range: WHOLE, ..Default::default() };
        let mut view = 0;
        // SAFETY: the device and image are alive; the description and what it chains live
        // through the call.
        unsafe { (self.calls.vkCreateImageView)(self.device, &seen, null(), &mut view) };
        view
    }

    /// Lets go of an import. (The device is done with it.)
    fn let_go_of(&self, imported: Imported) {
        let (calls, device) = (&self.calls, self.device);
        // SAFETY: as said; null handles are let be.
        unsafe {
            (calls.vkDestroyImageView)(device, imported.view, null());
            (calls.vkDestroyImage)(device, imported.image, null());
            (calls.vkFreeMemory)(device, imported.memory, null());
            #[cfg(not(target_os = "android"))]
            (calls.vkDestroyBuffer)(device, imported.buffer, null());
            #[cfg(not(target_os = "android"))]
            (calls.vkFreeMemory)(device, imported.buffer_memory, null());
        }
    }

    /// Lets go of the kind made, and the buffers imported for it (their views go through its
    /// conversion). (The device is done with them.)
    fn forget_kind(&mut self) {
        std::mem::take(&mut self.imported).into_iter().for_each(|imported| self.let_go_of(imported));
        let Some(kind) = self.kind.take() else { return };
        let (calls, device) = (&self.calls, self.device);
        // SAFETY: each is held once, by the kind; null handles are let be.
        unsafe {
            (calls.vkDestroyPipeline)(device, kind.pipeline, null());
            (calls.vkDestroyPipelineLayout)(device, kind.layout, null());
            (calls.vkDestroyDescriptorPool)(device, kind.pool, null());
            (calls.vkDestroyDescriptorSetLayout)(device, kind.set_layout, null());
            (calls.vkDestroySampler)(device, kind.sampler, null());
            (calls.vkDestroySamplerYcbcrConversion)(device, kind.conversion, null());
        }
    }
}

impl Drop for Frames {
    /// Lets go of everything. (The device is done with all of it.)
    fn drop(&mut self) {
        self.forget_kind();
    }
}

/// What a frame's kind is made of: what tells it apart, its format (0: the driver's own,
/// `external`), and the format's features.
#[derive(Clone, Copy)]
struct KindOf {
    key: [u64; 2],
    format: u32,
    features: u32,
    #[cfg(target_os = "android")]
    external: VkExternalFormatANDROID,
}

impl KindOf {
    /// What a conversion or an image of this kind chains in: its driver's own format, where it
    /// has one.
    fn chained(&self) -> *const c_void {
        #[cfg(target_os = "android")]
        if self.format == 0 {
            return (&raw const self.external).cast();
        }
        null()
    }
}

// ---- Android: the image reader's hardware buffers ----

/// The queue family of what is outside Vulkan (`VK_QUEUE_FAMILY_FOREIGN_EXT`); a layout any use
/// takes (`VK_IMAGE_LAYOUT_GENERAL`); memory of a hardware buffer
/// (`VK_EXTERNAL_MEMORY_HANDLE_TYPE_ANDROID_HARDWARE_BUFFER_BIT_ANDROID`).
#[cfg(target_os = "android")]
const FOREIGN: u32 = !2;
#[cfg(target_os = "android")]
const LAYOUT_GENERAL: u32 = 1;
#[cfg(target_os = "android")]
const HARDWARE_BUFFER: u32 = 0x400;

#[cfg(target_os = "android")]
impl Frames {
    /// A frame's hardware buffer as Vulkan sees it: its memory's size and kinds, and its format.
    fn properties(&self, frame: &FrameTexture) -> Option<(VkAndroidHardwareBufferPropertiesANDROID, VkAndroidHardwareBufferFormatPropertiesANDROID)> {
        let mut format = VkAndroidHardwareBufferFormatPropertiesANDROID { kind: 1_000_129_002, ..Default::default() };
        let mut properties = VkAndroidHardwareBufferPropertiesANDROID { kind: 1_000_129_000, next: (&raw mut format).cast(), ..Default::default() };
        // SAFETY: the device and the frame's buffer are alive; Vulkan fills in the chain.
        let said = unsafe { (self.calls.vkGetAndroidHardwareBufferPropertiesANDROID)(self.device, frame.buffer, &mut properties) };
        properties.next = std::ptr::null_mut();
        (said == 0).then_some((properties, format))
    }

    /// A frame's kind: its buffer's format, or the driver's own.
    fn kind_of(&self, frame: &FrameTexture) -> Option<KindOf> {
        let (_, format) = self.properties(frame)?;
        let external = VkExternalFormatANDROID { kind: 1_000_129_005, format: format.external_format, ..Default::default() };
        Some(KindOf { key: [format.format as u64, format.external_format], format: format.format, features: format.features, external })
    }

    /// `frame`'s hardware buffer imported as an image of its kind, with its view; the buffer
    /// held while imported.
    fn imported_of(&self, _: &Pipeline, frame: &FrameTexture, key: u64) -> Option<Imported> {
        let ((properties, format), kind) = (self.properties(frame)?, self.kind_of(frame)?);
        let (calls, device) = (&self.calls, self.device);
        let external = VkExternalMemoryImageCreateInfo { kind: 1_000_072_001, next: kind.chained(), handles: HARDWARE_BUFFER };
        let [width, height] = [frame.whole.0, frame.whole.1];
        let asked = VkImageCreateInfo {
            kind: 14,
            next: (&raw const external).cast(),
            image_type: 1,
            format: format.format,
            extent: [width, height, 1],
            mip_levels: 1,
            array_layers: 1,
            samples: 1,
            usage: USAGE_SAMPLED,
            ..Default::default()
        };
        let mut imported = Imported { key, image: 0, memory: 0, view: 0, used: false, _held: frame.hold_buffer() };
        // SAFETY: the device is alive; the description and its chain live through the call.
        let made = unsafe { (calls.vkCreateImage)(device, &asked, null(), &mut imported.image) } == 0;
        let dedicated = VkMemoryDedicatedAllocateInfo { kind: 1_000_127_001, image: imported.image, ..Default::default() };
        let buffer = VkImportAndroidHardwareBufferInfoANDROID { kind: 1_000_129_003, next: (&raw const dedicated).cast(), buffer: frame.buffer };
        let memory = VkMemoryAllocateInfo { kind: 5, next: (&raw const buffer).cast(), size: properties.size, type_index: properties.memory_types.trailing_zeros() };
        // SAFETY: as above; the image takes all of the memory.
        let bound = made && unsafe { (calls.vkAllocateMemory)(device, &memory, null(), &mut imported.memory) == 0 && (calls.vkBindImageMemory)(device, imported.image, imported.memory, 0) == 0 };
        imported.view = if bound { self.view(imported.image, format.format) } else { 0 };
        if imported.view == 0 {
            self.let_go_of(imported);
            return None;
        }
        Some(imported)
    }

    /// Takes this part's frames from the shaders back to the decoder, once drawn (to the
    /// foreign queue family).
    pub(crate) fn give_back(&self, commands: Object) {
        for at in &self.drawn {
            let given =
                VkImageMemoryBarrier { source_family: self.family, destination_family: FOREIGN, ..barrier(self.imported[*at].image, LAYOUT_SHADER_READ_ONLY, LAYOUT_GENERAL, ACCESS_SHADER_READ, 0) };
            // SAFETY: the commands are being recorded; the image is alive.
            unsafe { (self.calls.vkCmdPipelineBarrier)(commands, STAGE_FRAGMENT_SHADER, STAGE_BOTTOM, 0, 0, null(), 0, null(), 1, &given) };
        }
    }

    /// Takes the frame's image from the decoder for the shaders (from the foreign queue family:
    /// what the decoder wrote is kept).
    fn lay_out(&mut self, commands: Object, at: usize, _: &FrameTexture) {
        let imported = &mut self.imported[at];
        let before = if std::mem::replace(&mut imported.used, true) { LAYOUT_GENERAL } else { LAYOUT_UNDEFINED };
        let taken = VkImageMemoryBarrier { source_family: FOREIGN, destination_family: self.family, ..barrier(imported.image, before, LAYOUT_SHADER_READ_ONLY, 0, ACCESS_SHADER_READ) };
        // SAFETY: the commands are being recorded; the image is alive.
        unsafe { (self.calls.vkCmdPipelineBarrier)(commands, STAGE_TOP, STAGE_FRAGMENT_SHADER, 0, 0, null(), 0, null(), 1, &taken) };
    }
}

// ---- Linux: dmabufs ----

/// Two- and three-plane 4:2:0 formats (`VK_FORMAT_G8_B8R8_2PLANE_420_UNORM`,
/// `…G8_B8_R8_3PLANE_420_UNORM`); each plane's aspect; memory of a dmabuf
/// (`VK_EXTERNAL_MEMORY_HANDLE_TYPE_DMA_BUF_BIT_EXT`).
#[cfg(not(target_os = "android"))]
const TWO_PLANES: u32 = 1_000_156_003;
#[cfg(not(target_os = "android"))]
const THREE_PLANES: u32 = 1_000_156_002;
#[cfg(not(target_os = "android"))]
const PLANES: [u32; 3] = [0x10, 0x20, 0x40];
#[cfg(not(target_os = "android"))]
const DMA_BUF: u32 = 0x200;

/// What `physical` can do with images of `format` laid out its own way (optimal tiling).
#[cfg(not(target_os = "android"))]
fn optimal_features(vulkan: &Vulkan, physical: Object, format: u32) -> u32 {
    let found = vulkan.function(c"vkGetPhysicalDeviceFormatProperties");
    if found.is_null() {
        return 0;
    }
    let mut properties = VkFormatProperties::default();
    // SAFETY: the function of that name, as vulkan_core.h declares it; it fills in the
    // properties.
    unsafe { std::mem::transmute::<*const c_void, unsafe extern "system" fn(Object, u32, *mut VkFormatProperties)>(found)(physical, format, &mut properties) };
    properties.optimal
}

#[cfg(not(target_os = "android"))]
impl Frames {
    /// A frame's kind: its planes' format.
    fn kind_of(&self, frame: &FrameTexture) -> Option<KindOf> {
        let (format, features) = match frame.dmabuf.planes.len() {
            2 => (TWO_PLANES, self.planar[0]),
            3 => (THREE_PLANES, self.planar[1]),
            _ => return None,
        };
        Some(KindOf { key: [format as u64, 0], format, features })
    }

    /// `frame`'s dmabuf imported as a buffer (its file duplicated, handed to Vulkan), and an
    /// image of its kind's planes it is copied into, with its view.
    fn imported_of(&self, pipeline: &Pipeline, frame: &FrameTexture, key: u64) -> Option<Imported> {
        let format = self.kind_of(frame)?.format;
        let mut imported = Imported { key, image: 0, memory: 0, view: 0, buffer: 0, buffer_memory: 0 };
        let made = self.import_buffer(frame, &mut imported) && self.planes_image(pipeline, frame, format, &mut imported);
        imported.view = if made { self.view(imported.image, format) } else { 0 };
        if imported.view == 0 {
            self.let_go_of(imported);
            return None;
        }
        Some(imported)
    }

    /// Imports the frame's dmabuf as a buffer copies read from: whether it did.
    fn import_buffer(&self, frame: &FrameTexture, imported: &mut Imported) -> bool {
        use std::os::fd::{BorrowedFd, IntoRawFd};
        let (calls, device) = (&self.calls, self.device);
        let external = VkExternalMemoryBufferCreateInfo { kind: 1_000_072_000, handles: DMA_BUF, ..Default::default() };
        let asked = VkBufferCreateInfo { kind: 12, next: (&raw const external).cast(), size: frame.dmabuf.size, usage: USAGE_TRANSFER_SOURCE, ..Default::default() };
        let (mut needs, mut fd_kinds) = (VkMemoryRequirements::default(), VkMemoryFdPropertiesKHR { kind: 1_000_074_001, ..Default::default() });
        // SAFETY: the device is alive; the frame's file is open while it lives.
        let file = unsafe { BorrowedFd::borrow_raw(frame.dmabuf.fd) }.try_clone_to_owned();
        let Ok(file) = file else { return false };
        // SAFETY: as above; the description and its chain live through the call.
        unsafe {
            if (calls.vkCreateBuffer)(device, &asked, null(), &mut imported.buffer) != 0 || (calls.vkGetMemoryFdPropertiesKHR)(device, DMA_BUF, frame.dmabuf.fd, &mut fd_kinds) != 0 {
                return false;
            }
            (calls.vkGetBufferMemoryRequirements)(device, imported.buffer, &mut needs);
        }
        let kinds = needs.type_bits & fd_kinds.memory_types;
        let dedicated = VkMemoryDedicatedAllocateInfo { kind: 1_000_127_001, buffer: imported.buffer, ..Default::default() };
        let mut handed = VkImportMemoryFdInfoKHR { kind: 1_000_074_000, next: (&raw const dedicated).cast(), handle: DMA_BUF, fd: -1 };
        let raw = file.into_raw_fd();
        handed.fd = raw;
        let memory = VkMemoryAllocateInfo { kind: 5, next: (&raw const handed).cast(), size: needs.size.max(frame.dmabuf.size), type_index: kinds.trailing_zeros() };
        // SAFETY: as above; Vulkan owns the file once the memory is made, else it is closed here.
        let made = kinds != 0 && unsafe { (calls.vkAllocateMemory)(device, &memory, null(), &mut imported.buffer_memory) } == 0;
        if !made {
            // SAFETY: the file duplicated above, not handed over.
            drop(unsafe { <std::os::fd::OwnedFd as std::os::fd::FromRawFd>::from_raw_fd(raw) });
            return false;
        }
        // SAFETY: as above; the buffer takes all of the memory.
        unsafe { (calls.vkBindBufferMemory)(device, imported.buffer, imported.buffer_memory, 0) == 0 }
    }

    /// An image of `format`'s planes, the frame's size, in the device's own memory, that
    /// copies fill and shaders read: whether it is made.
    fn planes_image(&self, pipeline: &Pipeline, frame: &FrameTexture, format: u32, imported: &mut Imported) -> bool {
        let (calls, device, mut needs) = (&self.calls, self.device, VkMemoryRequirements::default());
        let asked = VkImageCreateInfo {
            kind: 14,
            image_type: 1,
            format,
            extent: [frame.whole.0, frame.whole.1, 1],
            mip_levels: 1,
            array_layers: 1,
            samples: 1,
            usage: USAGE_SAMPLED | USAGE_TRANSFER_DESTINATION,
            ..Default::default()
        };
        // SAFETY: the device is alive; the description is whole.
        unsafe {
            if (calls.vkCreateImage)(device, &asked, null(), &mut imported.image) != 0 {
                return false;
            }
            (calls.vkGetImageMemoryRequirements)(device, imported.image, &mut needs);
        }
        let Some(memory) = pipeline.memory(needs, pipeline.local) else { return false };
        imported.memory = memory;
        // SAFETY: as above.
        unsafe { (calls.vkBindImageMemory)(device, imported.image, memory, 0) == 0 }
    }

    /// Copies the frame's planes from its dmabuf into its image, then readies that for the
    /// shaders.
    fn lay_out(&mut self, commands: Object, at: usize, frame: &FrameTexture) {
        let imported = &self.imported[at];
        let [width, height] = [frame.whole.0, frame.whole.1];
        let copies: Vec<VkBufferImageCopy> = frame.dmabuf.planes.iter().enumerate().map(|(nth, plane)| plane_copy(nth, plane, [width, height], frame.dmabuf.planes.len())).collect();
        let to_copy = barrier(imported.image, LAYOUT_UNDEFINED, LAYOUT_TRANSFER_DESTINATION, 0, ACCESS_TRANSFER_WRITE);
        let to_read = barrier(imported.image, LAYOUT_TRANSFER_DESTINATION, LAYOUT_SHADER_READ_ONLY, ACCESS_TRANSFER_WRITE, ACCESS_SHADER_READ);
        // SAFETY: the commands are being recorded; each copy lies in the buffer (as the dmabuf's
        // planes do) and in its plane of the image.
        unsafe {
            (self.calls.vkCmdPipelineBarrier)(commands, STAGE_TOP, STAGE_TRANSFER, 0, 0, null(), 0, null(), 1, &to_copy);
            (self.calls.vkCmdCopyBufferToImage)(commands, imported.buffer, imported.image, LAYOUT_TRANSFER_DESTINATION, copies.len() as u32, copies.as_ptr());
            (self.calls.vkCmdPipelineBarrier)(commands, STAGE_TRANSFER, STAGE_FRAGMENT_SHADER, 0, 0, null(), 0, null(), 1, &to_read);
        }
    }
}

/// The copy of plane `nth` of a dmabuf of `planes` planes (where it starts, and its bytes a
/// row) into its plane of an image `size` big: all of the first, half each way of the others
/// (two bytes a sample in the second of two).
#[cfg(not(target_os = "android"))]
fn plane_copy(nth: usize, plane: &crate::video_gstreamer::Plane, [width, height]: [u32; 2], planes: usize) -> VkBufferImageCopy {
    let (extent, bytes) = match nth {
        0 => ([width, height], 1),
        _ => ([width.div_ceil(2), height.div_ceil(2)], if planes == 2 { 2 } else { 1 }),
    };
    VkBufferImageCopy { buffer_offset: plane.offset, row_length: plane.pitch / bytes, layers: [PLANES[nth], 0, 0, 1], extent: [extent[0], extent[1], 1], ..Default::default() }
}

/// The fragment shader's GLSL with videos' frames before `FROM_YUV`, `TEXEL_GLSL`, `SHADING` and
/// `gpu_draw_vulkan::PIXELS_GLSL`: the cache and patches (set 0), four frames through their
/// conversion (set 1), and the numbers that make each RGB (pushed, eight a frame).
#[cfg(test)]
const FRAMES_GLSL: &str = r#"#version 450
#define as_float uintBitsToFloat
layout(set = 0, binding = 0) uniform sampler2D cache;
layout(set = 0, binding = 1) uniform sampler2D patches;
layout(set = 1, binding = 0) uniform sampler2D frame0;
layout(set = 1, binding = 1) uniform sampler2D frame1;
layout(set = 1, binding = 2) uniform sampler2D frame2;
layout(set = 1, binding = 3) uniform sampler2D frame3;
layout(push_constant) uniform Numbers { vec4 of[8]; } numbers;
"#;

/// How a texel is read: the cache's, the patches', or frame n's (texture 2 + n) made RGB. A
/// frame reads Cr, Y and Cb as red, green and blue (the identity model), a quarter pixel into
/// the pixel: its chroma is then sample x / 2 whether the conversion places chroma at the
/// middle of its pixels or on the first.
#[cfg(test)]
const TEXEL_GLSL: &str = r#"
vec4 frame_texel(sampler2D frame, vec4 a, vec4 b, int x, int y) {
    vec3 read = textureLod(frame, (vec2(x, y) + 0.25) / b.zw, 0.0).rgb;
    return from_yuv(floor(read.gbr * 255.0 + 0.5), a, b);
}
vec4 texel(int which, int x, int y) {
    if (which == 0) {
        return texelFetch(cache, ivec2(x, y), 0);
    } else if (which == 1) {
        return texelFetch(patches, ivec2(x, y), 0);
    } else if (which == 2) {
        return frame_texel(frame0, numbers.of[0], numbers.of[1], x, y);
    } else if (which == 3) {
        return frame_texel(frame1, numbers.of[2], numbers.of[3], x, y);
    } else if (which == 4) {
        return frame_texel(frame2, numbers.of[4], numbers.of[5], x, y);
    }
    return frame_texel(frame3, numbers.of[6], numbers.of[7], x, y);
}
"#;

/// The fragment shader with frames, whole.
#[cfg(test)]
fn pixels_glsl() -> String {
    use crate::{gpu_draw::SHADING, gpu_draw_vulkan::PIXELS_GLSL, video_yuv::FROM_YUV};
    format!("{FRAMES_GLSL}{FROM_YUV}{TEXEL_GLSL}{SHADING}{PIXELS_GLSL}")
}

