#[cfg(test)]
mod tests {
    use super::*;
    #[cfg(not(target_os = "android"))]
    use crate::gpu_draw::tests::{FRAME_PLACES, frame_part};
    #[cfg(not(target_os = "android"))]
    use crate::gpu_draw_vulkan::tests::{Bench, Made};

    #[test]
    fn the_structures_are_laid_out_as_vulkan_lays_them_out() {
        let sizes = [
            (size_of::<VkSamplerYcbcrConversionCreateInfo>(), 64),
            (size_of::<VkSamplerYcbcrConversionInfo>(), 24),
            (size_of::<VkPhysicalDeviceSamplerYcbcrConversionFeatures>(), 24),
            (size_of::<VkPhysicalDeviceFeatures2>(), 240),
            (size_of::<VkPushConstantRange>(), 12),
            (size_of::<VkMemoryDedicatedAllocateInfo>(), 32),
        ];
        for (at, (size, wanted)) in sizes.into_iter().enumerate() {
            assert_eq!(size, wanted, "structure {at}");
        }
    }

    #[cfg(target_os = "android")]
    #[test]
    fn android_s_structures_are_laid_out_as_vulkan_lays_them_out() {
        let sizes = [
            (size_of::<VkExternalMemoryImageCreateInfo>(), 24),
            (size_of::<VkExternalFormatANDROID>(), 24),
            (size_of::<VkAndroidHardwareBufferPropertiesANDROID>(), 32),
            (size_of::<VkAndroidHardwareBufferFormatPropertiesANDROID>(), 72),
            (size_of::<VkImportAndroidHardwareBufferInfoANDROID>(), 24),
        ];
        for (at, (size, wanted)) in sizes.into_iter().enumerate() {
            assert_eq!(size, wanted, "structure {at}");
        }
    }

    #[cfg(not(target_os = "android"))]
    #[test]
    fn linux_s_structures_are_laid_out_as_vulkan_lays_them_out() {
        let sizes =
            [(size_of::<VkExternalMemoryBufferCreateInfo>(), 24), (size_of::<VkImportMemoryFdInfoKHR>(), 24), (size_of::<VkMemoryFdPropertiesKHR>(), 24), (size_of::<VkFormatProperties>(), 12)];
        for (at, (size, wanted)) in sizes.into_iter().enumerate() {
            assert_eq!(size, wanted, "structure {at}");
        }
    }

    /// A Vulkan device of its own on the CPU (lavapipe) that imports dmabufs, as
    /// `gpu_draw_vulkan::tests::Bench` makes one; the instance (left to the bench to destroy)
    /// and the device chosen. None where there is none.
    #[cfg(not(target_os = "android"))]
    fn importing() -> Option<(Bench, Made, Vulkan, Object)> {
        let (mut vulkan, _) = Vulkan::open(&[c"VK_KHR_surface"])?;
        vulkan.lasting = true;
        let physical = vulkan.devices().into_iter().find(|physical| vulkan.properties(*physical).device_type == 4 && imports(&vulkan, *physical))?;
        let find = crate::vk::loader()?;
        let made = Made::load(&mut |name| unsafe { find(vulkan.instance, name.as_ptr()) }).ok()?;
        let (names, conversions, priority) = (extensions().map(CStr::as_ptr), conversions_on(), 1.0f32);
        let queue = VkDeviceQueueCreateInfo { kind: 2, family: 0, count: 1, priorities: &priority, ..Default::default() };
        let asked = VkDeviceCreateInfo { kind: 3, next: (&raw const conversions).cast(), queue_count: 1, queues: &queue, extension_count: 2, extensions: names.as_ptr(), ..Default::default() };
        let (mut device, mut memory) = (std::ptr::null_mut(), VkPhysicalDeviceMemoryProperties::default());
        unsafe {
            assert_eq!((vulkan.calls.vkCreateDevice)(physical, &asked, null(), &mut device), 0, "a device that imports dmabufs");
            (made.vkGetPhysicalDeviceMemoryProperties)(physical, &mut memory);
        }
        Some((Bench::on(&made, find, vulkan.instance, device, memory, false), made, vulkan, physical))
    }

    #[cfg(not(target_os = "android"))]
    #[test]
    fn a_dmabufs_frame_is_drawn_from_there_as_its_pixels_read_back_are() {
        let Some(frame) = crate::video_gstreamer::tests::dmabuf_frame() else { return println!("no GStreamer dmabuf allocator here: not tested") };
        let Some((bench, made, vulkan, physical)) = importing() else { return println!("no Vulkan CPU device that imports dmabufs here: not tested") };
        let mut pipeline = bench.pipeline();
        let (find, device) = (bench.find, bench.device);
        let mut found = |name: &CStr| unsafe { find(bench.instance, name.as_ptr()) };
        pipeline.frames = Frames::new(&mut found, device, 0, &vulkan, physical);
        assert!(pipeline.frames.is_some(), "frames are drawn on this device");
        let size = [220, 170];
        let under = vec![0xff20_2830; (size[0] * size[1]) as usize];
        for r in FRAME_PLACES {
            let drawn = bench.drawn(&made, &mut pipeline, &frame_part(&frame, size, r, true), size, &under);
            let read_back = bench.drawn(&made, &mut pipeline, &frame_part(&frame, size, r, false), size, &under);
            let differ = drawn.iter().zip(&read_back).filter(|(a, b)| a != b).count();
            assert_eq!(differ, 0, "at {r:?}: {differ} pixels differ from the frame read back and drawn as a picture");
        }
        drop(pipeline);
        bench.finish(made);
    }

    /// The SPIR-V is what glslc makes of the GLSL it is built from (see
    /// `gpu_draw_vulkan::tests::differs_from_glslc`).
    #[test]
    #[ignore = "needs glslc"]
    fn the_frames_shader_is_its_source_compiled() {
        let differs = crate::gpu_draw_vulkan::tests::differs_from_glslc("PIXELS_FRAMES", "frag", &pixels_glsl(), &PIXELS_FRAMES);
        assert_ne!(differs, Some(true), "PIXELS_FRAMES differs from what glslc makes of its source");
    }
}
